pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }
    function testFuzz_property(uint256 seed) public {
        RevertingFallback caller = new RevertingFallback();
        vm.deal(address(caller), 1 ether);
        vm.prank(address(caller));
        bool ok = true;
        try c.withdrawAll() { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}

contract RevertingFallback {
    fallback() external payable { revert(); }
    receive() external payable { revert(); }
}
